--
-- Table structure for table `ai_xiaoai_session`
--

DROP TABLE IF EXISTS `ai_xiaoai_session`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_xiaoai_session` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `start_time` datetime NOT NULL COMMENT '会话开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '会话结束时间',
  `total_seconds` int DEFAULT '0' COMMENT '本次会话总时长(秒)',
  `end_reason` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '结束原因: timeout/manual/error/expired',
  `status` tinyint DEFAULT '1' COMMENT '状态: 1-进行中, 0-已结束',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_start_time` (`start_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='小爱倾听-会话记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

