DROP TABLE IF EXISTS `appointment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `appointment` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `patient_contact_id` bigint DEFAULT NULL COMMENT '就诊人ID',
  `doctor_id` bigint NOT NULL COMMENT '医生ID',
  `schedule_id` bigint NOT NULL COMMENT '排班ID',
  `status` int DEFAULT '0' COMMENT '状态(0-待就诊, 1-已完成, 2-已取消, 3-爽约)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `description` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '病情描述/病例表',
  `fee` decimal(10,2) DEFAULT '0.00' COMMENT '挂号费',
  `pay_status` int DEFAULT '0' COMMENT '支付状态(0-未支付, 1-已支付, 2-已退款)',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `type` int DEFAULT '0' COMMENT '0-offline, 1-online',
  `is_rescheduled` int DEFAULT '0' COMMENT '0-no, 1-yes',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='预约记录表';
