-- Table structure for table `article`
--

DROP TABLE IF EXISTS `article`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `article` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '文章标题',
  `content` longtext COLLATE utf8mb4_general_ci COMMENT '文章内容(富文本)',
  `cover_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '封面图URL',
  `type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT 'SCIENCE' COMMENT '类型(SCIENCE-科普, CASE-案例)',
  `status` int DEFAULT '1' COMMENT '状态(0-草稿, 1-已发布)',
  `author_id` bigint DEFAULT NULL COMMENT '作者ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `like_count` int DEFAULT '0' COMMENT '点赞数',
  `dislike_count` int DEFAULT '0' COMMENT '踩数',
  `collection_count` int DEFAULT '0' COMMENT '收藏数',
  `comment_count` int DEFAULT '0' COMMENT '评论数',
  `view_count` int DEFAULT '0' COMMENT '阅读数',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='心理文章表';
