DROP TABLE IF EXISTS `article_audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `article_audit_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `article_id` bigint NOT NULL COMMENT '文章ID',
  `article_type` int NOT NULL COMMENT '文章类型(1-管理员文章,2-用户文章)',
  `user_id` bigint NOT NULL COMMENT '发布者ID',
  `auditor_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `action` int NOT NULL COMMENT '操作(1-通过,2-拒绝,3-下架)',
  `reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '原因',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_article_id` (`article_id`),
  KEY `idx_auditor_id` (`auditor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文章审核记录';
