INSERT INTO `book` VALUES (1,'思考，快与慢','https://xinyuzhilian-aiadolescentmentalhealthsystem.oss-cn-beijing.aliyuncs.com/course/cover/20260408/7681dc0cb3ed4bf9828a73535ab30ebc.jpg','在《思考，快与慢》一书中，卡尼曼会带领我们体验一次思维的终极之旅。他认为，我们的大脑有快与慢两种作决定的方式。常用的无意识的“系统1”依赖情感、记忆和经验迅速作出判断，它见闻广博，使我们能够迅速对眼前的情况作出反应。但系统1也很容易上当，它固守“眼见即为事实”的原则，任由损失厌恶和乐观偏见之类的错觉引导我们作出错误的选择。有意识的“系统2”通过调动注意力来分析和解决问题，并作出决定，它比较慢，不容易出错，但它很懒惰，经常走捷径，直接采纳系统1的直觉型判断结果。','luoxiadushu.com/kuaiyuman/',30,1,10,1,'2026-04-08 19:29:16','2026-05-30 12:33:13',0);
/*!40000 ALTER TABLE `book` ENABLE KEYS */;
UNLOCK TABLES;

