--
-- Table structure for table `patient_profile`
--

DROP TABLE IF EXISTS `patient_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `patient_profile` (
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `emergency_contact` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '紧急联系人',
  `emergency_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '紧急电话',
  `medical_history` text COLLATE utf8mb4_general_ci COMMENT '既往病史',
  `tags` json DEFAULT NULL COMMENT '标签(抑郁倾向等)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
