INSERT INTO `psychologist` VALUES (1,1,'魏辰益',1,'','','',NULL,'',3,'0','0',0.00,0,0,NULL,NULL,NULL,1,0,0,'2026-04-14 22:31:06','2026-05-30 15:03:28'),(2,16,'魏定奎',1,'https://xinyuzhilian-aiadolescentmentalhealthsystem.oss-cn-beijing.aliyuncs.com/psychologist/20260415/b46b194777da4ea98d75b99f9c867105.png','我是心理咨询师魏定奎，拥有三年专业心理咨询从业经验，国家一级心理咨询师资格证书，先后系统学习精神分析、认知行为疗法（CBT）、人本主义疗法等主流咨询技术，持续接受个人体验与督导，累计咨询时长超X小时，致力于为来访者提供专业、安全、温暖的心理支持与成长陪伴。\n在咨询工作中，我始终秉持“尊重、理解、接纳、赋能”的核心理念，坚信每个人都拥有自我疗愈的力量，而我的角色，是陪伴你拨开心理的迷雾，梳理情绪的脉络，找到内心的力量，学会与自己和解、与生活相处。我不做评判，不强行灌输观点，而是以真诚的倾听、专业的引导，为你创造一个安全、包容的心理空间，让你可以安心地表达真实的自己，释放积压的情绪，探索问题的根源。\n\n从业以来，我专注于多个咨询领域，擅长处理：情绪困扰（焦虑、抑郁、愤怒、孤独、内耗等）、人际关系问题（亲子关系、亲密关系、职场人际关系冲突、社交恐惧等）、自我成长议题（自我认同、低自尊、完美主义、人生迷茫、压力管理等），同时也能为青少年心理疏导、婚姻家庭矛盾调解提供专业支持。\n\n我深知，每一次主动寻求咨询的勇气，都值得被珍视；每一段陷入困境的时光，都需要被温柔陪伴。无论是短期的情绪疏导，还是长期的个人成长探索，我都会始终坚守专业伦理，严格保护来访者的隐私，用专业的能力、真诚的态度，陪你走过低谷，见证你慢慢成长、慢慢发光。\n\n愿每一个在黑暗中徘徊的人，都能找到前行的光；愿每一颗疲惫的心灵，都能得到温柔的安放。如果你正被情绪困扰、被关系纠缠、对自我充满困惑，不妨勇敢迈出一步，我在这里，陪你一起，与更好的自己相遇。','我毕业于清华大学应用心理学专业（硕士），系统研习普通心理学、发展心理学、临床心理学、心理测量与评估等核心课程，打下了扎实的心理学理论基础；后续又通过持续深造，完成诚意心理咨询专项培训、诚意疗法进阶课程，不断夯实专业能力。','参与青少年心理疏导专项培训、婚姻家庭咨询实务课程，定期参加行业案例督导会、心理咨询伦理培训，持续吸收前沿咨询理念与实操方法，不断提升自身专业素养与咨询能力。我持续接受个人体验与督导，累计咨询时长超120小时，致力于为来访者提供专业、安全、温暖的心理支持与成长陪伴。',NULL,3,'500.0','700.0',5.00,2,1,'广东省清远市','清新区太平镇诚意心理咨询室','普通话,英语,粤语,上海话',1,1,0,'2026-04-15 19:00:27','2026-05-30 13:23:30');
/*!40000 ALTER TABLE `psychologist` ENABLE KEYS */;
UNLOCK TABLES;

