  `report_result` int DEFAULT '-1' COMMENT '案例报告结果(-1-未提交,0-待审核,1-通过,2-失败)',
  `interview_result` int DEFAULT '-1' COMMENT '面谈结果(-1-未开始,0-待审核,1-通过,2-失败)',
