  `username` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户名',
  `password` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码(加密)',
  `role` int DEFAULT '0' COMMENT '角色(0-游客, 1-用户, 2-医生, 3-医院管理员, 4-超级管理员)',
  `nickname` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '昵称',
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号',
  `email` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '邮箱（登录账号）',
  `is_psychologist` tinyint DEFAULT '0' COMMENT '是否为心理咨询师(0-否,1-是)',
  `email_verified` tinyint(1) DEFAULT '0' COMMENT '邮箱是否已验证(0-否,1-是)',
  `email_change_count` int NOT NULL DEFAULT '0' COMMENT '当月邮箱修改次数',
