DROP TABLE IF EXISTS `user_article`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_article` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '鏂囩珷鏍囬?',
  `content` longtext COLLATE utf8mb4_general_ci COMMENT '鏂囩珷鍐呭?',
  `cover_url` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '灏侀潰鍥',
  `tag_id` bigint DEFAULT NULL COMMENT '鏍囩?ID',
  `status` int DEFAULT '0' COMMENT '鐘舵?(0-寰呭?鏍?1-宸插彂甯?2-宸蹭笅鏋?',
  `reject_reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '鎷掔粷/涓嬫灦鍘熷洜',
  `like_count` int DEFAULT '0' COMMENT '鐐硅禐鏁',
  `dislike_count` int DEFAULT '0' COMMENT '韪╂暟',
  `collection_count` int DEFAULT '0' COMMENT '鏀惰棌鏁',
  `comment_count` int DEFAULT '0' COMMENT '璇勮?鏁',
  `view_count` int DEFAULT '0' COMMENT '闃呰?鏁',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_status` (`status`),
  KEY `idx_tag_id` (`tag_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='鐢ㄦ埛鏂囩珷琛';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `user_article`
--

LOCK TABLES `user_article` WRITE;
/*!40000 ALTER TABLE `user_article` DISABLE KEYS */;
INSERT INTO `user_article` VALUES (1,1,'焦虑的真相：成长过程中的六道“坎”','失业、绩效、催婚、社恐……总好像有个东西在刺激我们的神经，没有办法让我们安定下来。\n\n\n\n是的，焦虑。“焦虑”已经成为了时代病，我们太熟悉它了，熟悉到形影不离，熟悉到很难再找到一个不焦虑的人。\n\n\n\n但，关于焦虑，我们了解多少呢？\n\n\n\n当因为项目可能失败而恐慌到失眠时，那种“天要塌了我要完了”的窒息感，是否隐约有种世界末日般的绝望？\n\n\n\n当害怕在社交场合被否定、被排斥时，心底是否有个微弱的声音在尖叫：“他们不喜欢我！我要被抛弃了！”？\n\n\n\n当在竞争中感到“我不够好，随时会被取代”的威胁时，是否像在警惕一个看不见的敌人？\n\n\n\n其实，啃噬我们内心的焦虑感，它的“源代码”比你想象的要古老得多。\n\n\n\n它不仅关乎眼前的账单和老板的脸色，更连接着你生命的最初几年，那个还不会说话、无法理解世界和自身的婴儿，所经历的关乎“to be or not to be”的“生死体验”。\n\n\n\n我们的意识深处储存着婴儿期和童年早期为了构建自我、理解世界、建立联结而必须经历的阶段性焦虑。\n\n\n\n而我们被现实事件所折磨的焦虑感，其实是这些焦虑被激活后，披上了现代外衣的强烈回响。\n\n\n\n这些阶段性的焦虑有哪些呢？在精神分析家们的临床观察和研究下，按照婴孩的心智发展，建构出了以下这六种焦虑：','https://xinyuzhilian-aiadolescentmentalhealthsystem.oss-cn-beijing.aliyuncs.com/article/cover/20260320/be6f77d8b064485294d063f6fa18b3b5.png',3,1,'管理员下架',3,0,0,2,0,'2026-03-20 21:33:44','2026-03-25 23:56:41'),(2,1,'一起去看流星雨','# 让我们一起去看流星雨\n## 有人会问了，世界上真的真的有流星雨吗？\n这个文章会告诉你答案，做好你们的笔记准备上车咯~\n\n没有~','https://xinyuzhilian-aiadolescentmentalhealthsystem.oss-cn-beijing.aliyuncs.com/article/cover/20260508/92fe5fa946b84be3b362bd72e63a3cae.png',2,1,NULL,0,0,0,0,0,'2026-05-08 20:51:58','2026-05-30 01:08:19');
/*!40000 ALTER TABLE `user_article` ENABLE KEYS */;
UNLOCK TABLES;

